INSERT INTO sources (source_id, source_type, title, scope) VALUES
 ('SRC_ATTAR_TADHKIRAT','primary text','Farid al-Din Attar, Tadhkirat al-Awliya (Memorial of the Saints, c. 1220)','Islamic/Sufi'),
 ('SRC_JAMI_NAFAHAT','primary text','Jami, Nafahat al-Uns (Breaths of Fellowship, 1478)','Islamic/Sufi')
INSERT INTO _e VALUES
 ('ENT_SUF_NAQSHBANDI','Naqshbandiyya','Collective','Sufi order','Islamic/Sufi','silent dhikr; sober Sufism; sharia-bound spirituality; the Khwajagan lineage','A','Major Sunni Sufi tariqa traced to Baha al-Din Naqshband, distinguished by silent dhikr (dhikr-i khafi) and tracing its silsila to Abu Bakr.'),
 ('ENT_SUF_CHISHTI','Chishtiyya','Collective','Sufi order','Islamic/Sufi','sama (audition); service to the poor; love of God; South Asian Sufism','A','Sufi order rooted in Chisht (Afghanistan) and established in India by Mu''in al-Din Chishti, central to the Islamization of the subcontinent.'),
 ('ENT_SUF_BEKTASHI','Bektashiyya','Collective','Sufi order','Islamic/Sufi','Anatolian heterodoxy; Alevi devotion; veneration of Ali; antinomian piety','A','Heterodox Anatolian Sufi order traced to Hajji Bektash Wali, later linked to the Janissaries and to Alevi communities.'),
 ('ENT_SUF_NIMATULLAHI','Ni''matullahiyya','Collective','Sufi order','Islamic/Sufi','Persian Sufism; wahdat al-wujud; poetry and devotion','A','Persian Sufi order founded by Shah Ni''matullah Wali, the most widespread tariqa in Iran.'),
 ('ENT_SUF_KUBRAWI','Kubrawiyya','Collective','Sufi order','Islamic/Sufi','visionary mysticism; colours of the soul; Central Asian Sufism','A','Central Asian Sufi order founded by Najm al-Din Kubra, noted for its visionary psychology of luminous colours.'),
 ('ENT_SUF_BADAWIYYA','Badawiyya','Collective','Sufi order','Islamic/Sufi','Egyptian popular Sufism; saint-veneration; the Tanta mawlid','A','Egyptian Sufi order centred on the shrine of Ahmad al-Badawi at Tanta, host to one of the largest mawlid festivals in Islam.'),
 ('ENT_SUF_KUBRA','Najm al-Din Kubra','Saint','Tariqa founder','Islamic/Sufi','visionary mysticism; spiritual psychology; sainthood','B','Persian mystic (d. 1221), eponymous founder of the Kubrawiyya; martyred at the Mongol sack of Khwarazm. Author of works on the visionary lights of the soul.'),
 ('ENT_SUF_QUNAWI','Sadr al-Din al-Qunawi','Saint','Sufi saint (wali)','Islamic/Sufi','metaphysics; wahdat al-wujud; theology of unveiling','B','Persian-Anatolian metaphysician (d. 1274), stepson and chief successor of Ibn al-Arabi who systematized his teaching of the oneness of being.'),
 ('ENT_SUF_IRAQI','Fakhr al-Din Iraqi','Saint','Saint-poet','Islamic/Sufi','mystical love-poetry; wahdat al-wujud; divine beauty','B','Persian Sufi poet (d. 1289), disciple of Qunawi''s circle, whose Lama''at expounds Ibn al-Arabi''s doctrine through the imagery of love.'),
 ('ENT_SUF_KIRMANI','Awhad al-Din Kirmani','Saint','Saint-poet','Islamic/Sufi','contemplation of divine beauty; quatrains; the witness (shahid)','B','Persian Sufi master and poet (d. 1238) known for the contemplation of divine beauty in created forms (shahid-bazi) and for his ruba''iyat.'),
 ('ENT_SUF_CHISHTI_MUIN','Mu''in al-Din Chishti','Saint','Tariqa founder','Islamic/Sufi','sainthood; service to the poor; conversion; Indian Sufism','B','Persian saint (d. 1236) who established the Chishtiyya in India; his shrine (dargah) at Ajmer is among the most venerated in South Asia. Titled Gharib Nawaz.'),
 ('ENT_SUF_BAKHTIAR_KAKI','Qutb al-Din Bakhtiar Kaki','Saint','Sufi saint (wali)','Islamic/Sufi','sainthood; sama; the Delhi Chishti line','B','Chishti saint of Delhi (d. 1235), foremost disciple of Mu''in al-Din Chishti; his shrine at Mehrauli anchors the Delhi Chishti tradition.'),
 ('ENT_SUF_BABA_FARID','Farid al-Din Ganj-i-Shakar','Saint','Sufi saint (wali)','Islamic/Sufi','asceticism; Punjabi devotion; sainthood','B','Punjabi Chishti saint (d. 1265), ''Baba Farid''; his verses are included in the Sikh Guru Granth Sahib. Shrine at Pakpattan.'),
 ('ENT_SUF_NIZAM_AWLIYA','Nizam al-Din Awliya','Saint','Sufi saint (wali)','Islamic/Sufi','sainthood; love and tolerance; Delhi Sultanate Sufism','B','Pre-eminent Chishti saint of Delhi (d. 1325), ''Mahbub-i Ilahi''; his dargah is a major South Asian pilgrimage centre.'),
 ('ENT_SUF_AMIR_KHUSROW','Amir Khusrow','Saint','Saint-poet','Islamic/Sufi','Persian and Hindavi poetry; qawwali; devotion to the master','B','Indo-Persian poet and musician (d. 1325), devoted disciple of Nizam al-Din Awliya and a father of the qawwali devotional song.'),
 ('ENT_SUF_NAQSHBAND','Baha al-Din Naqshband','Saint','Tariqa founder','Islamic/Sufi','silent dhikr; sober Sufism; the Khwajagan path','B','Central Asian saint of Bukhara (d. 1389), eponym of the Naqshbandiyya, who emphasized silent remembrance and presence in the world.'),
 ('ENT_SUF_KHWAJA_AHRAR','Khwaja Ubayd Allah Ahrar','Saint','Sufi saint (wali)','Islamic/Sufi','sainthood; political influence; Naqshbandi consolidation','B','Naqshbandi master of Samarqand (d. 1490) who gave the order great political and economic weight under the Timurids.'),
 ('ENT_SUF_BADAWI','Ahmad al-Badawi','Saint','Tariqa founder','Islamic/Sufi','Egyptian popular sainthood; miracle-working; the Tanta mawlid','B','Saint of Tanta (d. 1276), eponym of the Badawiyya and one of the most popular saints of Egypt.'),
 ('ENT_SUF_DASUQI','Ibrahim al-Dasuqi','Saint','Tariqa founder','Islamic/Sufi','Egyptian sainthood; the four ''aqtab''; devotion','B','Egyptian saint (d. 1296), eponym of the Dasuqiyya (Burhaniyya) and counted among the four great qutbs of Egyptian Sufism.'),
 ('ENT_SUF_NIMATULLAH','Shah Ni''matullah Wali','Saint','Tariqa founder','Islamic/Sufi','Persian sainthood; mystical poetry; wahdat al-wujud','B','Persian saint and poet (d. 1431), founder of the Ni''matullahi order; his shrine at Mahan is a major Iranian pilgrimage site.'),
 ('ENT_SUF_BEKTASH','Hajji Bektash Wali','Saint','Tariqa founder','Islamic/Sufi','Anatolian sainthood; antinomian piety; veneration of Ali','B','Anatolian saint (d. 1271) revered as the founder-patron of the Bektashiyya and of Alevi devotion.'),
 ('ENT_SUF_YUNUS_EMRE','Yunus Emre','Saint','Saint-poet','Islamic/Sufi','Turkish devotional poetry; divine love; folk mysticism','B','Turkish saint-poet (d. 1321), father of Turkish-language Sufi poetry whose hymns of divine love remain central to Anatolian devotion.'),
 ('ENT_SUF_HAFIZ','Hafiz of Shiraz','Saint','Saint-poet','Islamic/Sufi','Persian ghazal; mystical love and wine; divine beauty','B','Persian lyric poet (d. 1390), ''Lisan al-Ghayb'', whose ghazals fuse the imagery of love and wine with mystical longing; venerated and used for bibliomancy (fal).'),
 ('ENT_SUF_SHABISTARI','Mahmud Shabistari','Saint','Saint-poet','Islamic/Sufi','mystical metaphysics; wahdat al-wujud; symbolic exegesis','B','Persian Sufi poet (d. 1340) whose Gulshan-i Raz (Rose Garden of Mystery) is a classic verse summary of Ibn al-Arabi''s metaphysics.'),
 ('ENT_SUF_JILI','Abd al-Karim al-Jili','Saint','Sufi saint (wali)','Islamic/Sufi','metaphysics; the Perfect Man (al-insan al-kamil); wahdat al-wujud','B','Yemeni-Iraqi mystic (d. c. 1424) whose al-Insan al-Kamil developed Ibn al-Arabi''s doctrine of the Perfect Man.'),
 ('ENT_SUF_SAFI_ARDABILI','Safi al-Din Ardabili','Saint','Tariqa founder','Islamic/Sufi','sainthood; the Safavid order; Azerbaijani Sufism','B','Persian saint of Ardabil (d. 1334), eponym of the Safaviyya order from which the Safavid dynasty later arose.'),
 ('ENT_SUF_HAMADANI','Sayyid Ali Hamadani','Saint','Sufi saint (wali)','Islamic/Sufi','missionary sainthood; Kubrawi path; Kashmiri Sufism','B','Persian Kubrawi saint (d. 1385) credited with spreading Islam and Persianate culture in Kashmir; ''Shah-i Hamadan''.'),
 ('ENT_SUF_MANERI','Sharaf al-Din Maneri','Saint','Sufi saint (wali)','Islamic/Sufi','sainthood; spiritual letters; Firdausi-Suhrawardi path','B','Indian Sufi master of Bihar (d. 1381) of the Firdausiyya (a Suhrawardi branch), famed for his Maktubat (Hundred Letters) of spiritual counsel.'),
 ('ENT_SUF_LAL_DED','Lal Ded','Saint','Saint-poet','Islamic/Sufi','Kashmiri mystical verse; non-dual devotion; the rishi tradition','C','Kashmiri mystic poet (d. c. 1392), ''Lalla'', whose vakhs voice a non-dual devotion bridging Shaiva and Sufi piety; revered by Hindus and Muslims alike.'),
 ('ENT_SUF_NURI','Nur al-Din Nurani','Saint','Tariqa founder','Islamic/Sufi','Kashmiri sainthood; the Rishi order; asceticism','C','Kashmiri saint (d. c. 1440), ''Nund Rishi'', patron-founder of the Kashmiri Rishi order; venerated as Alamdar-i Kashmir.'),
 ('ENT_SUF_JAMI','Abd al-Rahman Jami','Saint','Saint-poet','Islamic/Sufi','Persian poetry; Naqshbandi devotion; hagiography; wahdat al-wujud','B','Persian poet and Naqshbandi mystic (d. 1492), last of the great classical Persian poets; his Nafahat al-Uns is a major saints'' hagiography.');
