 ('ENT_SUF_BEKTASH','member_of','ENT_SUF_BEKTASHI','high','Founder-patron of the Bektashiyya.'),
 ('ENT_SUF_NIMATULLAH','member_of','ENT_SUF_NIMATULLAHI','high','Founder of the Ni''matullahi order.'),
 ('ENT_SUF_BADAWI','member_of','ENT_SUF_BADAWIYYA','high','Eponymous founder of the Badawiyya.'),
